-- Email verification (invite OTP) bookkeeping.
--
-- Supabase Auth owns the 6-digit code itself (generated by admin.generateLink and
-- checked by auth.verifyOtp). This table only tracks *when* a code was issued so the
-- app can enforce, server-side and independent of the Auth project settings:
--   * a 5-minute validity window per code,
--   * a 60-second resend cooldown that survives refreshes / tabs / direct API calls,
--   * a cap on verification attempts per code (no unlimited guessing).
-- The raw OTP is never stored here.

create table public.email_verification_challenges (
  user_id uuid primary key references auth.users (id) on delete cascade,
  -- Opaque handle used in the /verify-email link. Not an auth token: it cannot
  -- verify anything without the emailed code.
  id uuid not null unique default gen_random_uuid(),
  email text not null,
  sent_at timestamptz not null default now(),
  expires_at timestamptz not null,
  attempts integer not null default 0,
  send_count integer not null default 1,
  verified_at timestamptz,
  created_at timestamptz not null default now(),
  constraint email_verification_challenges_attempts_non_negative check (attempts >= 0)
);

comment on table public.email_verification_challenges is
  'Invite OTP timing/attempt state. Never stores the OTP. Service role only.';

-- Service role only: no policies, so anon/authenticated get nothing.
alter table public.email_verification_challenges enable row level security;
revoke all on public.email_verification_challenges from anon, authenticated;

-- Atomically (re)issue a code window. Returns issued = false, with the current
-- timings, when the previous code was sent less than p_cooldown_seconds ago, so
-- concurrent or repeated calls can never send two codes inside the cooldown.
create or replace function public.issue_email_verification(
  p_user_id uuid,
  p_email text,
  p_cooldown_seconds integer default 60,
  p_ttl_seconds integer default 300
)
returns table (
  challenge_id uuid,
  sent_at timestamptz,
  expires_at timestamptz,
  send_count integer,
  issued boolean
)
language plpgsql
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_now timestamptz := now();
begin
  return query
  insert into public.email_verification_challenges as c (
    user_id, email, sent_at, expires_at, attempts, send_count, verified_at
  )
  values (
    p_user_id, lower(p_email), v_now, v_now + make_interval(secs => p_ttl_seconds), 0, 1, null
  )
  on conflict (user_id) do update set
    email = excluded.email,
    sent_at = excluded.sent_at,
    expires_at = excluded.expires_at,
    attempts = 0,
    send_count = c.send_count + 1
  where c.verified_at is null
    and c.sent_at <= v_now - make_interval(secs => p_cooldown_seconds)
  returning c.id, c.sent_at, c.expires_at, c.send_count, true;

  if not found then
    return query
    select c.id, c.sent_at, c.expires_at, c.send_count, false
    from public.email_verification_challenges c
    where c.user_id = p_user_id;
  end if;
end;
$$;

-- Atomically spend one verification attempt on the current code before the code
-- is checked with Supabase Auth. Row lock serialises parallel guesses.
create or replace function public.consume_email_verification_attempt(
  p_challenge_id uuid,
  p_max_attempts integer default 5
)
returns table (
  outcome text,
  user_id uuid,
  email text,
  attempts_remaining integer
)
language plpgsql
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_row public.email_verification_challenges%rowtype;
begin
  select * into v_row
  from public.email_verification_challenges c
  where c.id = p_challenge_id
  for update;

  if not found then
    return query select 'not_found'::text, null::uuid, null::text, 0;
    return;
  end if;

  if v_row.verified_at is not null then
    return query select 'already_verified'::text, v_row.user_id, v_row.email, 0;
    return;
  end if;

  if v_row.expires_at <= now() then
    return query select 'expired'::text, v_row.user_id, v_row.email, 0;
    return;
  end if;

  if v_row.attempts >= p_max_attempts then
    return query select 'too_many'::text, v_row.user_id, v_row.email, 0;
    return;
  end if;

  update public.email_verification_challenges c
  set attempts = c.attempts + 1
  where c.user_id = v_row.user_id;

  return query
  select 'ok'::text, v_row.user_id, v_row.email, p_max_attempts - v_row.attempts - 1;
end;
$$;

revoke all on function public.issue_email_verification(uuid, text, integer, integer)
  from public, anon, authenticated;
revoke all on function public.consume_email_verification_attempt(uuid, integer)
  from public, anon, authenticated;
grant execute on function public.issue_email_verification(uuid, text, integer, integer)
  to service_role;
grant execute on function public.consume_email_verification_attempt(uuid, integer)
  to service_role;
